p-run-a-saga-whose-compensations-can-fai.prelude:
# Steps for the tests: a compensation that fails twice before it works, a failing action, and a no-op.
attempts = {"cancel_po": 0}


def cancel_po_flaky() -> None:
    attempts["cancel_po"] += 1
    if attempts["cancel_po"] < 3:
        raise ConnectionError("SAP timeout")


def fail() -> None:
    raise RuntimeError("step failed")


def noop() -> None:
    pass

p-run-a-saga-whose-compensations-can-fai.solution:
from collections.abc import Callable

Step = tuple[str, Callable[[], None], Callable[[], None]]


def run_saga(steps: list[Step], retries: int = 3) -> tuple[str, list[str]]:
    completed: list[Step] = []
    for step in steps:
        try:
            step[1]()
        except Exception:
            break
        completed.append(step)
    else:
        return "completed", []

    stuck: list[str] = []
    for name, _, compensate in reversed(completed):
        for _ in range(retries):
            try:
                compensate()
                break
            except Exception:
                continue
        else:
            stuck.append(name)  # every retry failed
    return ("needs_manual_intervention", stuck) if stuck else ("compensated", [])

